-- Check: sample records per register (10 each).
SELECT l.register_key, count(r.id) AS records
FROM public.local_registers l
LEFT JOIN public.local_register_records r ON r.register_id = l.id AND r.is_deleted = FALSE
WHERE l.id IN ('00000000-0000-4000-9003-000000000012'::uuid, '00000000-0000-4000-9003-000000000013'::uuid, '00000000-0000-4000-9003-000000000014'::uuid, '00000000-0000-4000-9003-000000000015'::uuid, '00000000-0000-4000-9003-000000000016'::uuid, '00000000-0000-4000-9003-000000000017'::uuid, '00000000-0000-4000-9003-000000000018'::uuid, '00000000-0000-4000-9003-000000000019'::uuid)
GROUP BY l.register_key ORDER BY l.register_key;
